// serialFraction inverts Amdahl's law for one measurement.
func serialFraction(speedup float64, workers int) float64 {
	n := float64(workers)
	return (1/speedup - 1/n) / (1 - 1/n)
}

// serialFraction(4, 8) == 0.142857...

